package com.pharmapack.qms.qa; import com.pharmapack.qms.batch.Batch; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="qa_reviews") @Getter @Setter @NoArgsConstructor public class QAReview { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="batch_id") Batch batch; Long reviewerId; String reviewType; String decision="PENDING"; LocalDateTime reviewDate; String comments; }
